  Future<List<SharedCourseInfo>> lookupPreview(String raw);

  /// 匯入並存成他人課表。認不得回 null。格子當下就畫得出來，課名之後補。
  Future<SharedTableInfo?> importShareCode(String raw);

  /// 補上他人課表的課名、教室與老師並存回去，回傳補完的格線。查不到的課保持原樣。
  Future<CourseGrid?> restoreSharedTable(String id);

  /// 移除 [day]、[section] 那一格的課並存回去，照 `CourseController.removeCourse`。找不到回 null。
  Future<CourseGrid?> removeCourse(int day, int section);

  /// 改 [day]、[section] 那一格的課號並存回去，照 `editCourseCellId`。找不到回 null。
